<style>
    /* ===== Technologies We Use Section Styles (unique prefixed classes, no *{}, body{}, :root{}) ===== */

    .techUse-wrapper {
        font-family: 'Segoe UI', Arial, sans-serif;
        width: 100%;
        box-sizing: border-box;
        background-color: #d9d9da;
        padding: 40px 50px;
    }

    .techUse-wrapper *,
    .techUse-wrapper *::before,
    .techUse-wrapper *::after {
        box-sizing: border-box;
    }

    .techUse-grid {
        max-width: 1400px;
        margin: 0 auto;
        display: grid;
        grid-template-columns: 1.15fr 1fr;
        gap: 28px;
        align-items: stretch;
    }

    /* ============ NEW: CONTENT + CAPSTONE PROJECTS ============ */
    .techUse-capBlock {
        max-width: 1400px;
        margin: 0 auto 44px auto;
    }

    .techUse-mainTitle {
        font-size: 26px;
        font-weight: 800;
        color: #1f1b3a;
        margin: 0 0 8px 0;
        line-height: 1.3;
    }

    .techUse-subText {
        font-size: 14px;
        line-height: 1.7;
        color: #5a5a66;
        margin: 0 0 30px 0;
        max-width: 820px;
    }

    .techUse-subText strong {
        color: #4b2fb0;
    }

    .techUse-capGrid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 18px;
    }

    .techUse-capCard {
        background: #ecebeb;
        border: 1px solid #eceef4;
        border-radius: 16px;
        padding: 24px 20px;
        display: flex;
        flex-direction: column;
        gap: 12px;
        opacity: 0;
        transform: translateY(16px);
        animation: techUseFadeUp 0.5s ease forwards;
        transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
    }

    .techUse-capCard:nth-child(1) { animation-delay: 0.05s; }
    .techUse-capCard:nth-child(2) { animation-delay: 0.15s; }
    .techUse-capCard:nth-child(3) { animation-delay: 0.25s; }
    .techUse-capCard:nth-child(4) { animation-delay: 0.35s; }

    .techUse-capCard:hover {
        transform: translateY(-6px);
        border-color: #7b2ff7;
        box-shadow: 0 16px 30px rgba(75, 47, 176, 0.14);
    }

    .techUse-capIcon {
        width: 46px;
        height: 46px;
        border-radius: 12px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: linear-gradient(135deg, #7b2ff7 0%, #4b2fb0 100%);
        color: #ffffff;
    }

    .techUse-capIcon svg {
        width: 24px;
        height: 24px;
    }

    .techUse-capCard h3 {
        font-size: 16px;
        font-weight: 800;
        color: #1f1b3a;
        margin: 0;
        line-height: 1.35;
    }

    .techUse-capCard p {
        font-size: 13px;
        line-height: 1.65;
        color: #5a5a66;
        margin: 0;
    }

    .techUse-tags {
        display: flex;
        flex-wrap: wrap;
        gap: 6px;
        margin-top: auto;
        padding-top: 4px;
    }

    .techUse-tag {
        font-size: 11px;
        font-weight: 700;
        color: #4b2fb0;
        background: #f0ebff;
        border-radius: 20px;
        padding: 4px 10px;
    }

    /* ============ LEFT: TECH LOGOS ============ */
    .techUse-leftCol {
        display: flex;
        flex-direction: column;
    }

    .techUse-sectionTitle {
        font-size: 14px;
        font-weight: 800;
        letter-spacing: 1.2px;
        color: #4b2fb0;
        margin: 0 0 16px 0;
    }

    .techUse-logosCard {
        flex: 1;
        background-color: #ecebeb;
        border: 1px solid #eceef4;
        border-radius: 16px;
        padding: 26px 18px;
        display: grid;
        grid-template-columns: repeat(6, 1fr);
        gap: 10px;
    }

    .techUse-logoItem {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: flex-start;
        gap: 12px;
        padding: 6px 4px;
        border-radius: 12px;
        opacity: 0;
        transform: translateY(16px);
        animation: techUseFadeUp 0.5s ease forwards;
        transition: transform 0.3s ease;
    }

    .techUse-logoItem:nth-child(1) {
        animation-delay: 0.05s;
    }

    .techUse-logoItem:nth-child(2) {
        animation-delay: 0.13s;
    }

    .techUse-logoItem:nth-child(3) {
        animation-delay: 0.21s;
    }

    .techUse-logoItem:nth-child(4) {
        animation-delay: 0.29s;
    }

    .techUse-logoItem:nth-child(5) {
        animation-delay: 0.37s;
    }

    .techUse-logoItem:nth-child(6) {
        animation-delay: 0.45s;
    }

    .techUse-logoItem:hover {
        transform: translateY(-6px);
    }

    .techUse-logoIconWrap {
        width: 46px;
        height: 46px;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: transform 0.4s ease;
    }

    .techUse-logoItem:hover .techUse-logoIconWrap {
        transform: scale(1.14) rotate(-4deg);
    }

    .techUse-logoIconWrap svg {
        width: 100%;
        height: 100%;
        display: block;
    }

    .techUse-logoLabel {
        font-size: 12.5px;
        font-weight: 600;
        color: #4a4a52;
        text-align: center;
    }

    @keyframes techUseFadeUp {
        from {
            opacity: 0;
            transform: translateY(16px);
        }

        to {
            opacity: 1;
            transform: translateY(0);
        }
    }

    /* ============ RIGHT: CTA CARD ============ */
    .techUse-ctaCard {
        position: relative;
        border-radius: 20px;
        padding: 34px 38px;
        background: linear-gradient(135deg, #7b2ff7 0%, #4b2fb0 55%, #3a2fc7 100%);
        color: #ffffff;
        overflow: hidden;
        display: flex;
        align-items: center;
        gap: 24px;
        box-shadow: 0 20px 40px rgba(75, 47, 176, 0.28);
    }

    .techUse-ctaGlow {
        position: absolute;
        top: -50px;
        right: -50px;
        width: 180px;
        height: 180px;
        border-radius: 50%;
        background-color: rgba(255, 255, 255, 0.08);
        animation: techUseGlowPulse 4s ease-in-out infinite;
    }

    @keyframes techUseGlowPulse {

        0%,
        100% {
            transform: scale(1);
            opacity: 0.8;
        }

        50% {
            transform: scale(1.2);
            opacity: 1;
        }
    }

    /* ---- Illustration ---- */
    .techUse-illustration {
        position: relative;
        z-index: 1;
        width: 140px;
        height: 140px;
        flex-shrink: 0;
    }

    .techUse-illustration svg {
        width: 100%;
        height: 100%;
        animation: techUseFloatIllus 4s ease-in-out infinite;
    }

    @keyframes techUseFloatIllus {

        0%,
        100% {
            transform: translateY(0px);
        }

        50% {
            transform: translateY(-8px);
        }
    }

    .techUse-cubeFloat {
        animation: techUseCubeFloat 3.2s ease-in-out infinite;
        transform-origin: center;
    }

    @keyframes techUseCubeFloat {

        0%,
        100% {
            transform: translateY(0px) rotate(0deg);
        }

        50% {
            transform: translateY(-10px) rotate(8deg);
        }
    }

    /* ---- Content ---- */
    .techUse-ctaContent {
        position: relative;
        z-index: 1;
        flex: 1;
    }

    .techUse-ctaTitle {
        font-size: 21px;
        font-weight: 800;
        line-height: 1.3;
        margin: 0 0 10px 0;
    }

    .techUse-ctaText {
        font-size: 13.5px;
        line-height: 1.6;
        color: rgba(255, 255, 255, 0.85);
        margin: 0 0 22px 0;
        max-width: 360px;
    }

    .techUse-ctaBtn {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        border: none;
        border-radius: 10px;
        padding: 12px 22px;
        font-size: 13.5px;
        font-weight: 700;
        color: #4b2fb0;
        background-color: #ffffff;
        cursor: pointer;
        transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    .techUse-ctaBtn:hover {
        transform: translateY(-3px);
        box-shadow: 0 10px 22px rgba(0, 0, 0, 0.2);
    }

    .techUse-ctaBtn svg {
        width: 15px;
        height: 15px;
        transition: transform 0.3s ease;
    }

    .techUse-ctaBtn:hover svg {
        transform: translateX(4px);
    }

    /* ===================== RESPONSIVE BREAKPOINTS ===================== */

    @media (max-width: 1024px) {
        .techUse-wrapper {
            padding: 34px 28px;
        }

        .techUse-grid {
            grid-template-columns: 1fr;
            gap: 24px;
        }

        .techUse-logosCard {
            grid-template-columns: repeat(6, 1fr);
        }

        .techUse-capGrid {
            grid-template-columns: repeat(2, 1fr);
        }
    }

    @media (max-width: 700px) {
        .techUse-logosCard {
            grid-template-columns: repeat(3, 1fr);
            gap: 18px 10px;
        }

        .techUse-ctaCard {
            flex-direction: column;
            align-items: flex-start;
            text-align: left;
        }

        .techUse-illustration {
            width: 110px;
            height: 110px;
        }

        .techUse-capGrid {
            grid-template-columns: 1fr;
        }

        .techUse-mainTitle {
            font-size: 21px;
        }
    }

    @media (max-width: 420px) {
        .techUse-wrapper {
            padding: 26px 16px;
        }

        .techUse-logosCard {
            grid-template-columns: repeat(2, 1fr);
            padding: 20px 14px;
        }

        .techUse-ctaCard {
            padding: 26px 24px;
        }

        .techUse-ctaTitle {
            font-size: 18px;
        }
    }
</style>

